package lineedit

import (
	"bufio"
	"path/filepath"
	"strings"
	"testing"
)

func TestBufferEditing(t *testing.T) {
	var b buffer
	for _, r := range "helo" {
		b.insert(r)
	}
	if b.string() != "helo" {
		t.Fatalf("got %q", b.string())
	}
	// Insert 'l' to fix "helo" -> "hello": move cursor before the last 'o'.
	b.left()
	b.insert('l')
	if b.string() != "hello" {
		t.Fatalf("insert-at-cursor got %q", b.string())
	}
	b.home()
	b.deleteFwd() // remove 'h'
	if b.string() != "ello" {
		t.Fatalf("deleteFwd got %q", b.string())
	}
	b.end()
	b.backspace() // remove trailing 'o'
	if b.string() != "ell" {
		t.Fatalf("backspace got %q", b.string())
	}
}

func TestBufferKills(t *testing.T) {
	var b buffer
	b.set("one two three")
	b.killWord() // cursor at end -> removes "three"
	if b.string() != "one two " {
		t.Fatalf("killWord got %q", b.string())
	}
	b.killLine()
	if b.string() != "" || b.pos != 0 {
		t.Fatalf("killLine got %q pos %d", b.string(), b.pos)
	}
	b.set("keep|cut")
	// place cursor after "keep" (index 4) and kill to end
	b.home()
	for i := 0; i < 4; i++ {
		b.right()
	}
	b.killToEnd()
	if b.string() != "keep" {
		t.Fatalf("killToEnd got %q", b.string())
	}
}

func decodeAll(t *testing.T, s string) []keyEvent {
	t.Helper()
	br := bufio.NewReader(strings.NewReader(s))
	var out []keyEvent
	for {
		k, err := decode(br)
		if err != nil {
			break
		}
		out = append(out, k)
	}
	return out
}

func TestDecodeKeys(t *testing.T) {
	cases := map[string]keyKind{
		"a":       keyRune,
		"\r":      keyEnter,
		"\n":      keyEnter,
		"\x7f":    keyBackspace,
		"\x03":    keyInterrupt,
		"\x04":    keyEOF,
		"\x01":    keyHome,
		"\x05":    keyEnd,
		"\x1b[A":  keyUp,
		"\x1b[B":  keyDown,
		"\x1b[C":  keyRight,
		"\x1b[D":  keyLeft,
		"\x1b[H":  keyHome,
		"\x1b[3~": keyDelete,
		"\x1bOA":  keyUp, // application cursor mode
	}
	for input, want := range cases {
		got := decodeAll(t, input)
		if len(got) == 0 || got[0].kind != want {
			t.Fatalf("decode %q: got %+v, want kind %d", input, got, want)
		}
	}
	if got := decodeAll(t, "x"); got[0].r != 'x' {
		t.Fatalf("rune decode got %q", got[0].r)
	}
}

func TestHistoryNavigation(t *testing.T) {
	e := &Editor{hist: []string{"first", "second", "third"}}
	var b buffer
	b.set("draft")
	cursor := len(e.hist)
	stash := ""

	e.histPrev(&b, &cursor, &stash) // -> third
	if b.string() != "third" {
		t.Fatalf("up1 got %q", b.string())
	}
	e.histPrev(&b, &cursor, &stash) // -> second
	e.histPrev(&b, &cursor, &stash) // -> first
	if b.string() != "first" {
		t.Fatalf("up3 got %q", b.string())
	}
	e.histPrev(&b, &cursor, &stash) // clamp at oldest
	if b.string() != "first" {
		t.Fatalf("clamp got %q", b.string())
	}
	e.histNext(&b, &cursor, &stash) // -> second
	e.histNext(&b, &cursor, &stash) // -> third
	e.histNext(&b, &cursor, &stash) // -> back to the stashed draft
	if b.string() != "draft" {
		t.Fatalf("restore stash got %q", b.string())
	}
}

func TestHistoryPersistence(t *testing.T) {
	path := filepath.Join(t.TempDir(), "sub", "coder.history")
	e := &Editor{path: path}
	e.add("build")
	e.add("build") // consecutive dup -> skipped
	e.add("  ")    // blank -> skipped
	e.add("test")

	got := loadHistory(path)
	if strings.Join(got, ",") != "build,test" {
		t.Fatalf("persisted history = %v", got)
	}
}

// Package lineedit is a small raw-mode line editor with per-file command
// history. It gives the interactive REPL arrow-key recall and basic editing
// (backspace, ^A/^E/^U/^K/^W, left/right, up/down) without a full readline
// dependency — only golang.org/x/term for raw mode. When the input is not a
// terminal it falls back to plain line reading, so pipes and scripts are
// unaffected.
package lineedit

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"

	"golang.org/x/term"
)

// ErrInterrupt is returned by ReadLine when the user presses Ctrl-C.
var ErrInterrupt = errors.New("lineedit: interrupted")

// Editor reads and edits a line, keeping history in memory and appending it to
// a history file.
type Editor struct {
	in    *os.File
	out   io.Writer
	fd    int
	isTTY bool
	br    *bufio.Reader
	hist  []string
	path  string
}

// New builds an editor over in/out, loading history from path (which may be "").
func New(in *os.File, out io.Writer, path string) *Editor {
	e := &Editor{in: in, out: out, fd: int(in.Fd()), br: bufio.NewReader(in), path: path}
	e.isTTY = term.IsTerminal(e.fd)
	e.hist = loadHistory(path)
	return e
}

// ReadLine reads one line. prompt is written before the input; promptWidth is
// its visible column width (used to position the cursor). It returns
// ErrInterrupt on Ctrl-C and io.EOF on Ctrl-D at an empty line / end of input.
func (e *Editor) ReadLine(prompt string, promptWidth int) (string, error) {
	if !e.isTTY {
		return e.readPlain()
	}
	old, err := term.MakeRaw(e.fd)
	if err != nil {
		return e.readPlain()
	}
	defer func() { _ = term.Restore(e.fd, old) }()
	return e.readRaw(prompt, promptWidth)
}

func (e *Editor) readPlain() (string, error) {
	line, err := e.br.ReadString('\n')
	line = strings.TrimRight(line, "\r\n")
	if err == io.EOF {
		if line == "" {
			return "", io.EOF
		}
		return line, nil
	}
	if err != nil {
		return "", err
	}
	return line, nil
}

func (e *Editor) readRaw(prompt string, promptWidth int) (string, error) {
	var b buffer
	cursor := len(e.hist) // len(hist) means "editing a fresh line"
	stash := ""
	e.redraw(prompt, promptWidth, &b)

	for {
		k, err := decode(e.br)
		if err != nil {
			fmt.Fprint(e.out, "\r\n")
			if err == io.EOF {
				return "", io.EOF
			}
			return "", err
		}
		switch k.kind {
		case keyEnter:
			fmt.Fprint(e.out, "\r\n")
			line := b.string()
			e.add(line)
			return line, nil
		case keyInterrupt:
			fmt.Fprint(e.out, "\r\n")
			return "", ErrInterrupt
		case keyEOF:
			if len(b.runes) == 0 {
				fmt.Fprint(e.out, "\r\n")
				return "", io.EOF
			}
			b.deleteFwd()
		case keyRune:
			b.insert(k.r)
		case keyBackspace:
			b.backspace()
		case keyDelete:
			b.deleteFwd()
		case keyLeft:
			b.left()
		case keyRight:
			b.right()
		case keyHome:
			b.home()
		case keyEnd:
			b.end()
		case keyKillToEnd:
			b.killToEnd()
		case keyKillLine:
			b.killLine()
		case keyKillWord:
			b.killWord()
		case keyUp:
			e.histPrev(&b, &cursor, &stash)
		case keyDown:
			e.histNext(&b, &cursor, &stash)
		case keyNone:
			continue // nothing changed; skip redraw
		}
		e.redraw(prompt, promptWidth, &b)
	}
}

// redraw repaints the input line: return to column 0, clear it, write the
// prompt and buffer, then position the cursor after promptWidth+pos columns.
func (e *Editor) redraw(prompt string, promptWidth int, b *buffer) {
	fmt.Fprintf(e.out, "\r\x1b[K%s%s\x1b[%dG", prompt, b.string(), promptWidth+b.pos+1)
}

func (e *Editor) histPrev(b *buffer, cursor *int, stash *string) {
	if len(e.hist) == 0 || *cursor == 0 {
		return
	}
	if *cursor == len(e.hist) {
		*stash = b.string()
	}
	*cursor--
	b.set(e.hist[*cursor])
}

func (e *Editor) histNext(b *buffer, cursor *int, stash *string) {
	if *cursor >= len(e.hist) {
		return
	}
	*cursor++
	if *cursor == len(e.hist) {
		b.set(*stash)
	} else {
		b.set(e.hist[*cursor])
	}
}

// Package terminal provides small, dependency-free helpers for styled terminal
// output: color detection, ANSI wrappers, box drawing, and screen control. It
// degrades to plain text when the output is not a terminal or NO_COLOR is set,
// so piped and scripted use is unaffected.
package terminal

import (
	"os"
	"strconv"
	"strings"
	"unicode/utf8"
)

// ANSI color codes.
const (
	codeReset   = "\033[0m"
	codeBold    = "1"
	codeDim     = "2"
	codeRed     = "31"
	codeGreen   = "32"
	codeYellow  = "33"
	codeMagenta = "35"
	codeCyan    = "36"
)

// Styler wraps text in ANSI codes when Color is true, and returns it unchanged
// otherwise.
type Styler struct{ Color bool }

// Detect returns a Styler enabled when f is a character device (a terminal).
// NO_COLOR forces plain output; CLICOLOR_FORCE forces styled output (useful
// when piping into a pager); NO_COLOR wins if both are set.
func Detect(f *os.File) Styler {
	if os.Getenv("NO_COLOR") != "" {
		return Styler{Color: false}
	}
	if os.Getenv("CLICOLOR_FORCE") != "" {
		return Styler{Color: true}
	}
	info, err := f.Stat()
	if err != nil {
		return Styler{Color: false}
	}
	return Styler{Color: info.Mode()&os.ModeCharDevice != 0}
}

func (s Styler) wrap(code, text string) string {
	if !s.Color {
		return text
	}
	return "\033[" + code + "m" + text + codeReset
}

func (s Styler) Bold(t string) string    { return s.wrap(codeBold, t) }
func (s Styler) Dim(t string) string     { return s.wrap(codeDim, t) }
func (s Styler) Red(t string) string     { return s.wrap(codeRed, t) }
func (s Styler) Green(t string) string   { return s.wrap(codeGreen, t) }
func (s Styler) Yellow(t string) string  { return s.wrap(codeYellow, t) }
func (s Styler) Magenta(t string) string { return s.wrap(codeMagenta, t) }
func (s Styler) Cyan(t string) string    { return s.wrap(codeCyan, t) }

// ClearScreen clears the visible screen and homes the cursor. Scrollback is
// preserved. It emits nothing when styling is disabled (non-terminal output).
func (s Styler) ClearScreen() string {
	if !s.Color {
		return ""
	}
	return "\033[H\033[2J"
}

// Width returns a usable line width, from COLUMNS when set, clamped to a sane
// range. It avoids a terminal-ioctl dependency by trusting the environment.
func Width() int {
	if c := os.Getenv("COLUMNS"); c != "" {
		if n, err := strconv.Atoi(c); err == nil && n > 0 {
			return clamp(n-1, 40, 100)
		}
	}
	return 72
}

func clamp(n, lo, hi int) int {
	if n < lo {
		return lo
	}
	if n > hi {
		return hi
	}
	return n
}

// TitledTop returns a top border with an embedded title: "┌─ title ─────┐".
func (s Styler) TitledTop(title string, width int) string {
	label := "─ " + title + " "
	fill := width - 2 - runeLen(label)
	if fill < 0 {
		fill = 0
	}
	return s.Dim("┌" + label + strings.Repeat("─", fill) + "┐")
}

// Row returns one boxed content row, padded to the box width. leadColored is an
// optional already-colored prefix (e.g. a status dot) whose plain form is
// leadPlain, used so padding stays correct despite color codes.
func (s Styler) Row(leadColored, leadPlain, text string, width int) string {
	inner := width - 2
	content := leadPlain + text
	pad := inner - 1 - runeLen(content) // one leading space inside the box
	if pad < 0 {
		pad = 0
	}
	body := " " + leadColored + text + strings.Repeat(" ", pad)
	return s.Dim("│") + body + s.Dim("│")
}

// Bottom returns the bottom border "└────┘".
func (s Styler) Bottom(width int) string {
	return s.Dim("└" + strings.Repeat("─", width-2) + "┘")
}

// PromptTop and PromptBottom draw the rounded input box borders.
func (s Styler) PromptTop(width int) string {
	return s.Dim("╭" + strings.Repeat("─", width-2) + "╮")
}

func (s Styler) PromptBottom(width int) string {
	return s.Dim("╰" + strings.Repeat("─", width-2) + "╯")
}

func runeLen(s string) int { return utf8.RuneCountInString(s) }

package herdr

import (
	"bufio"
	"encoding/json"
	"net"
	"path/filepath"
	"sync"
	"testing"
	"time"

	"github.com/emergingrobotics/erg/internal/agent"
)

type recordedReq struct {
	Method string         `json:"method"`
	Params map[string]any `json:"params"`
}

// fakeHerdr is an in-test socket server speaking herdr's newline-JSON protocol.
type fakeHerdr struct {
	ln   net.Listener
	mu   sync.Mutex
	reqs []recordedReq
}

func startFakeHerdr(t *testing.T) (*fakeHerdr, string) {
	t.Helper()
	sock := filepath.Join(t.TempDir(), "herdr.sock")
	ln, err := net.Listen("unix", sock)
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	f := &fakeHerdr{ln: ln}
	go f.serve()
	t.Cleanup(func() { ln.Close() })
	return f, sock
}

func (f *fakeHerdr) serve() {
	for {
		conn, err := f.ln.Accept()
		if err != nil {
			return
		}
		go func() {
			defer conn.Close()
			sc := bufio.NewScanner(conn)
			if !sc.Scan() {
				return
			}
			var req struct {
				ID     string         `json:"id"`
				Method string         `json:"method"`
				Params map[string]any `json:"params"`
			}
			if err := json.Unmarshal(sc.Bytes(), &req); err != nil {
				return
			}
			f.mu.Lock()
			f.reqs = append(f.reqs, recordedReq{Method: req.Method, Params: req.Params})
			f.mu.Unlock()
			resp, _ := json.Marshal(map[string]any{"id": req.ID, "result": map[string]any{}})
			conn.Write(append(resp, '\n'))
		}()
	}
}

func (f *fakeHerdr) recorded() []recordedReq {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]recordedReq, len(f.reqs))
	copy(out, f.reqs)
	return out
}

func TestClientDisabledWithoutEnv(t *testing.T) {
	c := New(Env{})
	if c.Enabled() {
		t.Fatal("client should be disabled without env")
	}
	c.ReportStatus(agent.StatusWorking) // must be a silent no-op
}

func TestReportStatusDedupsAndReports(t *testing.T) {
	f, sock := startFakeHerdr(t)
	c := New(Env{Active: true, SocketPath: sock, PaneID: "w1:p1"})

	c.ReportStatus(agent.StatusWorking)
	c.ReportStatus(agent.StatusWorking) // duplicate, suppressed
	c.ReportStatus(agent.StatusIdle)

	waitFor(t, func() bool { return len(f.recorded()) >= 2 })
	reqs := f.recorded()
	if len(reqs) != 2 {
		t.Fatalf("expected 2 reports (dedup), got %d: %+v", len(reqs), reqs)
	}
	if reqs[0].Method != "pane.report_agent" || reqs[0].Params["state"] != "working" {
		t.Fatalf("first report wrong: %+v", reqs[0])
	}
	if reqs[1].Params["state"] != "idle" {
		t.Fatalf("second report wrong: %+v", reqs[1])
	}
	if reqs[0].Params["pane_id"] != "w1:p1" {
		t.Fatalf("pane_id not sent (herdr requires pane_id, not pane): %+v", reqs[0].Params)
	}
}

func TestReportBlocked(t *testing.T) {
	f, sock := startFakeHerdr(t)
	c := New(Env{Active: true, SocketPath: sock, PaneID: "p"})
	c.ReportStatus(agent.StatusBlocked)
	waitFor(t, func() bool { return len(f.recorded()) >= 1 })
	if got := f.recorded()[0].Params["state"]; got != "blocked" {
		t.Fatalf("expected state blocked, got %v", got)
	}
}

func TestReportDoneReleasesAgent(t *testing.T) {
	// "done" is not a valid pane state; it must relinquish agent authority.
	f, sock := startFakeHerdr(t)
	c := New(Env{Active: true, SocketPath: sock, PaneID: "p"})
	c.ReportStatus(agent.StatusDone)
	waitFor(t, func() bool { return len(f.recorded()) >= 1 })
	req := f.recorded()[0]
	if req.Method != "pane.release_agent" {
		t.Fatalf("done should call pane.release_agent, got %s", req.Method)
	}
	if req.Params["pane_id"] != "p" {
		t.Fatalf("pane_id not sent: %+v", req.Params)
	}
}

func TestReleaseReleasesAgentAfterIdle(t *testing.T) {
	// A normal exit leaves the pane idle; Release must still relinquish agent
	// authority so herdr drops erg from the panel.
	f, sock := startFakeHerdr(t)
	c := New(Env{Active: true, SocketPath: sock, PaneID: "p"})
	c.ReportStatus(agent.StatusIdle)
	c.Release()
	waitFor(t, func() bool { return len(f.recorded()) >= 2 })
	last := f.recorded()[1]
	if last.Method != "pane.release_agent" {
		t.Fatalf("Release should call pane.release_agent, got %s", last.Method)
	}
	if last.Params["pane_id"] != "p" {
		t.Fatalf("pane_id not sent: %+v", last.Params)
	}
}

func TestReleaseDisabledIsNoop(t *testing.T) {
	c := New(Env{})
	c.Release() // must not panic or dial
}

func TestReportMetadata(t *testing.T) {
	f, sock := startFakeHerdr(t)
	c := New(Env{Active: true, SocketPath: sock, PaneID: "p"})
	c.ReportMetadata(map[string]string{"shape": "spec-implementer", "model": "mock"})

	waitFor(t, func() bool { return len(f.recorded()) >= 1 })
	reqs := f.recorded()
	if reqs[0].Method != "pane.report_metadata" {
		t.Fatalf("expected metadata method, got %s", reqs[0].Method)
	}
	tokens, ok := reqs[0].Params["tokens"].(map[string]any)
	if !ok || tokens["shape"] != "spec-implementer" {
		t.Fatalf("tokens not sent: %+v", reqs[0].Params)
	}
}

func TestReportSurvivesMissingSocket(t *testing.T) {
	// No server listening: the report must not panic or block.
	c := New(Env{Active: true, SocketPath: filepath.Join(t.TempDir(), "absent.sock"), PaneID: "p"})
	c.ReportStatus(agent.StatusWorking)
}

func waitFor(t *testing.T, cond func() bool) {
	t.Helper()
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		if cond() {
			return
		}
		time.Sleep(10 * time.Millisecond)
	}
	t.Fatal("condition not met before deadline")
}

package terminal

import (
	"strings"
	"testing"
	"unicode/utf8"
)

func TestDetectColorPrecedence(t *testing.T) {
	// CLICOLOR_FORCE enables even off a terminal.
	t.Setenv("NO_COLOR", "")
	t.Setenv("CLICOLOR_FORCE", "1")
	if !Detect(nil).Color {
		t.Fatal("CLICOLOR_FORCE should force color")
	}
	// NO_COLOR wins over CLICOLOR_FORCE.
	t.Setenv("NO_COLOR", "1")
	if Detect(nil).Color {
		t.Fatal("NO_COLOR must win over CLICOLOR_FORCE")
	}
}

func TestDisabledStylerIsPlain(t *testing.T) {
	s := Styler{Color: false}
	if s.Bold("hi") != "hi" || s.Red("x") != "x" {
		t.Fatal("disabled styler must not add codes")
	}
	if s.ClearScreen() != "" {
		t.Fatal("disabled styler must not clear the screen")
	}
}

func TestEnabledStylerWrapsAndResets(t *testing.T) {
	s := Styler{Color: true}
	got := s.Green("ok")
	if !strings.HasPrefix(got, "\033[32m") || !strings.HasSuffix(got, "\033[0m") {
		t.Fatalf("bad wrap: %q", got)
	}
}

// visibleLen strips ANSI escape sequences to measure on-screen width.
func visibleLen(s string) int {
	var b strings.Builder
	for i := 0; i < len(s); {
		if s[i] == '\033' {
			for i < len(s) && s[i] != 'm' {
				i++
			}
			i++ // skip the 'm'
			continue
		}
		_, size := utf8.DecodeRuneInString(s[i:])
		b.WriteString(s[i : i+size])
		i += size
	}
	return utf8.RuneCountInString(b.String())
}

func TestRowVisibleWidthMatchesBox(t *testing.T) {
	width := 40
	for _, s := range []Styler{{Color: false}, {Color: true}} {
		plain := s.Row("", "", "model · dgx · shape", width)
		dot := s.Row(s.Green("●")+" ", "● ", "idle", width)
		top := s.TitledTop("erg", width)
		bottom := s.Bottom(width)
		for _, line := range []string{plain, dot, top, bottom} {
			if got := visibleLen(line); got != width {
				t.Fatalf("line %q visible width = %d, want %d", line, got, width)
			}
		}
	}
}

func TestRowTruncatesLongText(t *testing.T) {
	s := Styler{Color: false}
	long := strings.Repeat("x", 200)
	line := s.Row("", "", long, 40)
	if visibleLen(line) < 40 {
		t.Fatalf("row should be at least the box width, got %d", visibleLen(line))
	}
}

func TestWidthClamp(t *testing.T) {
	t.Setenv("COLUMNS", "500")
	if w := Width(); w != 100 {
		t.Fatalf("expected clamp to 100, got %d", w)
	}
	t.Setenv("COLUMNS", "10")
	if w := Width(); w != 40 {
		t.Fatalf("expected clamp to 40, got %d", w)
	}
}

package herdr

import (
	"bufio"
	"encoding/json"
	"fmt"
	"net"
	"sync"
	"sync/atomic"
	"time"

	"github.com/emergingrobotics/erg/internal/agent"
)

const source = "erg"

// Client reports erg's state and metadata to herdr over its local socket. It
// is safe for concurrent use and is a no-op when herdr is not present.
type Client struct {
	env    Env
	reqID  atomic.Uint64
	dialer net.Dialer

	mu        sync.Mutex
	lastState agent.AgentStatus
	haveState bool
}

// New returns a client for the detected environment.
func New(env Env) *Client {
	return &Client{env: env, dialer: net.Dialer{Timeout: 2 * time.Second}}
}

// Enabled reports whether herdr is present.
func (c *Client) Enabled() bool { return c.env.Active && c.env.SocketPath != "" }

// ReportStatus publishes an authoritative agent status. Duplicate consecutive
// states are suppressed so herdr sees transitions, not noise. Errors are
// swallowed: a state report must never fail the agent.
//
// herdr's pane.report_agent accepts only idle/working/blocked as a live pane
// state; "done" is not a pane state, so a done report relinquishes the pane's
// agent authority via pane.release_agent instead.
func (c *Client) ReportStatus(s agent.AgentStatus) {
	if !c.Enabled() {
		return
	}
	c.mu.Lock()
	if c.haveState && c.lastState == s {
		c.mu.Unlock()
		return
	}
	c.lastState = s
	c.haveState = true
	c.mu.Unlock()

	if s == agent.StatusDone {
		c.releaseAgent()
		return
	}
	_ = c.call("pane.report_agent", map[string]any{
		"pane_id": c.env.PaneID,
		"source":  source,
		"agent":   source,
		"state":   s.String(),
	})
}

// Release relinquishes this pane's agent authority so herdr drops erg from the
// agents panel. It runs on shutdown regardless of the last reported state: a
// normal exit leaves the pane idle (not done), which would otherwise linger in
// the panel. No-op when herdr is absent; errors are swallowed.
func (c *Client) Release() {
	if !c.Enabled() {
		return
	}
	c.releaseAgent()
}

func (c *Client) releaseAgent() {
	_ = c.call("pane.release_agent", map[string]any{
		"pane_id": c.env.PaneID,
		"source":  source,
		"agent":   source,
	})
}

// ReportMetadata publishes display tokens (shape, model, task label) so a fleet
// is legible without attaching to the pane.
func (c *Client) ReportMetadata(tokens map[string]string) {
	if !c.Enabled() || len(tokens) == 0 {
		return
	}
	_ = c.call("pane.report_metadata", map[string]any{
		"pane_id": c.env.PaneID,
		"source":  source,
		"tokens":  tokens,
	})
}

type request struct {
	ID     string `json:"id"`
	Method string `json:"method"`
	Params any    `json:"params,omitempty"`
}

type response struct {
	ID    string `json:"id"`
	Error *struct {
		Code    string `json:"code"`
		Message string `json:"message"`
	} `json:"error"`
}

// call performs one newline-JSON request/response over the socket.
func (c *Client) call(method string, params any) error {
	conn, err := c.dialer.Dial("unix", c.env.SocketPath)
	if err != nil {
		return err
	}
	defer conn.Close()
	_ = conn.SetDeadline(time.Now().Add(2 * time.Second))

	id := fmt.Sprintf("erg-%d", c.reqID.Add(1))
	line, err := json.Marshal(request{ID: id, Method: method, Params: params})
	if err != nil {
		return err
	}
	if _, err := conn.Write(append(line, '\n')); err != nil {
		return err
	}

	sc := bufio.NewScanner(conn)
	sc.Buffer(make([]byte, 0, 8192), 1<<20)
	if !sc.Scan() {
		if err := sc.Err(); err != nil {
			return err
		}
		return fmt.Errorf("herdr: no response")
	}
	var resp response
	if err := json.Unmarshal(sc.Bytes(), &resp); err != nil {
		return err
	}
	if resp.Error != nil {
		return fmt.Errorf("herdr %s: %s", method, resp.Error.Message)
	}
	return nil
}

package lineedit

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// maxHistory bounds how many entries are kept in memory when loading.
const maxHistory = 2000

// loadHistory reads a history file into a slice, oldest first. A missing file
// yields an empty history.
func loadHistory(path string) []string {
	if path == "" {
		return nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var out []string
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimRight(line, "\r")
		if line != "" {
			out = append(out, line)
		}
	}
	if len(out) > maxHistory {
		out = out[len(out)-maxHistory:]
	}
	return out
}

// add appends line to the in-memory history and the history file, skipping
// blanks and consecutive duplicates.
func (e *Editor) add(line string) {
	if strings.TrimSpace(line) == "" {
		return
	}
	if n := len(e.hist); n > 0 && e.hist[n-1] == line {
		return
	}
	e.hist = append(e.hist, line)
	e.appendFile(line)
}

func (e *Editor) appendFile(line string) {
	if e.path == "" {
		return
	}
	if err := os.MkdirAll(filepath.Dir(e.path), 0o755); err != nil {
		return
	}
	f, err := os.OpenFile(e.path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
	if err != nil {
		return
	}
	defer f.Close()
	fmt.Fprintln(f, line)
}

package lineedit

import "bufio"

// buffer is an editable line of runes with a cursor. All editing operations are
// pure (no I/O), so they are unit-tested directly.
type buffer struct {
	runes []rune
	pos   int
}

func (b *buffer) string() string { return string(b.runes) }

func (b *buffer) set(s string) {
	b.runes = []rune(s)
	b.pos = len(b.runes)
}

func (b *buffer) insert(r rune) {
	b.runes = append(b.runes, 0)
	copy(b.runes[b.pos+1:], b.runes[b.pos:])
	b.runes[b.pos] = r
	b.pos++
}

func (b *buffer) backspace() {
	if b.pos == 0 {
		return
	}
	b.runes = append(b.runes[:b.pos-1], b.runes[b.pos:]...)
	b.pos--
}

func (b *buffer) deleteFwd() {
	if b.pos >= len(b.runes) {
		return
	}
	b.runes = append(b.runes[:b.pos], b.runes[b.pos+1:]...)
}

func (b *buffer) left() {
	if b.pos > 0 {
		b.pos--
	}
}

func (b *buffer) right() {
	if b.pos < len(b.runes) {
		b.pos++
	}
}

func (b *buffer) home() { b.pos = 0 }
func (b *buffer) end()  { b.pos = len(b.runes) }

func (b *buffer) killToEnd() { b.runes = b.runes[:b.pos] }

func (b *buffer) killLine() {
	b.runes = b.runes[:0]
	b.pos = 0
}

// killWord deletes the whitespace-delimited word before the cursor.
func (b *buffer) killWord() {
	i := b.pos
	for i > 0 && b.runes[i-1] == ' ' {
		i--
	}
	for i > 0 && b.runes[i-1] != ' ' {
		i--
	}
	b.runes = append(b.runes[:i], b.runes[b.pos:]...)
	b.pos = i
}

// keyKind classifies a decoded key press.
type keyKind int

const (
	keyNone keyKind = iota
	keyRune
	keyEnter
	keyBackspace
	keyDelete
	keyLeft
	keyRight
	keyHome
	keyEnd
	keyUp
	keyDown
	keyKillToEnd
	keyKillLine
	keyKillWord
	keyInterrupt
	keyEOF
)

type keyEvent struct {
	kind keyKind
	r    rune
}

// decode reads one key from br, translating control bytes and ANSI escape
// sequences (arrows, home/end, delete) into a keyEvent. It is pure over the
// reader, so it is tested by feeding byte slices.
func decode(br *bufio.Reader) (keyEvent, error) {
	b, err := br.ReadByte()
	if err != nil {
		return keyEvent{}, err
	}
	switch {
	case b == 0x0d || b == 0x0a:
		return keyEvent{kind: keyEnter}, nil
	case b == 0x03:
		return keyEvent{kind: keyInterrupt}, nil // Ctrl-C
	case b == 0x04:
		return keyEvent{kind: keyEOF}, nil // Ctrl-D
	case b == 0x7f || b == 0x08:
		return keyEvent{kind: keyBackspace}, nil
	case b == 0x01:
		return keyEvent{kind: keyHome}, nil // Ctrl-A
	case b == 0x05:
		return keyEvent{kind: keyEnd}, nil // Ctrl-E
	case b == 0x02:
		return keyEvent{kind: keyLeft}, nil // Ctrl-B
	case b == 0x06:
		return keyEvent{kind: keyRight}, nil // Ctrl-F
	case b == 0x10:
		return keyEvent{kind: keyUp}, nil // Ctrl-P
	case b == 0x0e:
		return keyEvent{kind: keyDown}, nil // Ctrl-N
	case b == 0x0b:
		return keyEvent{kind: keyKillToEnd}, nil // Ctrl-K
	case b == 0x15:
		return keyEvent{kind: keyKillLine}, nil // Ctrl-U
	case b == 0x17:
		return keyEvent{kind: keyKillWord}, nil // Ctrl-W
	case b == 0x1b:
		return decodeEscape(br)
	case b < 0x20:
		return keyEvent{kind: keyNone}, nil
	case b < 0x80:
		return keyEvent{kind: keyRune, r: rune(b)}, nil
	default:
		// UTF-8 multibyte lead: put it back and read the whole rune.
		_ = br.UnreadByte()
		r, _, err := br.ReadRune()
		if err != nil {
			return keyEvent{}, err
		}
		return keyEvent{kind: keyRune, r: r}, nil
	}
}

func decodeEscape(br *bufio.Reader) (keyEvent, error) {
	intro, err := br.ReadByte()
	if err != nil {
		return keyEvent{}, err
	}
	if intro != '[' && intro != 'O' {
		return keyEvent{kind: keyNone}, nil
	}
	b, err := br.ReadByte()
	if err != nil {
		return keyEvent{}, err
	}
	switch b {
	case 'A':
		return keyEvent{kind: keyUp}, nil
	case 'B':
		return keyEvent{kind: keyDown}, nil
	case 'C':
		return keyEvent{kind: keyRight}, nil
	case 'D':
		return keyEvent{kind: keyLeft}, nil
	case 'H':
		return keyEvent{kind: keyHome}, nil
	case 'F':
		return keyEvent{kind: keyEnd}, nil
	}
	if b >= '0' && b <= '9' {
		num := []byte{b}
		for {
			n, err := br.ReadByte()
			if err != nil {
				return keyEvent{}, err
			}
			if n < '0' || n > '9' {
				break // consume the trailing '~' (or other terminator)
			}
			num = append(num, n)
		}
		switch string(num) {
		case "3":
			return keyEvent{kind: keyDelete}, nil
		case "1", "7":
			return keyEvent{kind: keyHome}, nil
		case "4", "8":
			return keyEvent{kind: keyEnd}, nil
		}
	}
	return keyEvent{kind: keyNone}, nil
}

