func TestBufferEdgeCases(t *testing.T) {
	var b buffer

	// Empty buffer operations
	b.backspace()
	b.deleteFwd()
	b.left()
	if b.pos != 0 {
		t.Fatalf("empty buffer left moved cursor")
	}
	b.right()
	if b.pos != 0 {
		t.Fatalf("empty buffer right moved cursor")
	}
	b.killWord()
	b.killToEnd()
	b.killLine()
	if b.string() != "" || b.pos != 0 {
		t.Fatalf("empty buffer ops left state: %q pos %d", b.string(), b.pos)
	}

	// Single rune buffer
	b.set("x")
	b.left()
	if b.pos != 0 {
		t.Fatalf("single char left pos = %d", b.pos)
	}
	b.right()
	if b.pos != 1 {
		t.Fatalf("single char right pos = %d", b.pos)
	}
	b.deleteFwd()
	if b.string() != "x" {
		t.Fatalf("deleteFwd at end changed buffer")
	}
	b.left()
	b.deleteFwd()
	if b.string() != "" {
		t.Fatalf("deleteFwd at end should remove char")
	}

	// Multiple consecutive spaces
	b.set("a    b")
	b.home()
	for i := 0; i < 2; i++ {
		b.right()
	}
	b.killWord()
	if b.string() != "a b" {
		t.Fatalf("killWord with spaces got %q", b.string())
	}

	// UTF-8 characters
	b.set("日本語")
	if b.string() != "日本語" {
		t.Fatalf("UTF-8 buffer got %q", b.string())
	}
	b.left()
	if b.string() != "日本語" {
		t.Fatalf("UTF-8 left broke buffer")
	}
}

func TestCursorMovement(t *testing.T) {
	var b buffer
	b.set("hello world")

	// Test cursor at various positions
	b.home()
	if b.pos != 0 {
		t.Fatalf("home pos = %d", b.pos)
	}
	b.end()
	if b.pos != len("hello world") {
		t.Fatalf("end pos = %d", b.pos)
	}
	b.home()
	for i := 0; i < 6; i++ {
		b.right()
	}
	if b.pos != 6 {
		t.Fatalf("right movement pos = %d", b.pos)
	}
	for i := 0; i < 3; i++ {
		b.left()
	}
	if b.pos != 3 {
		t.Fatalf("left movement pos = %d", b.pos)
	}
}

func TestKillOperations(t *testing.T) {
	var b buffer

	// killToEnd from middle
	b.set("abcdef")
	b.home()
	for i := 0; i < 3; i++ {
		b.right()
	}
	b.killToEnd()
	if b.string() != "abc" {
		t.Fatalf("killToEnd got %q", b.string())
	}

	// killLine clears everything
	b.set("abc")
	b.killLine()
	if b.string() != "" || b.pos != 0 {
		t.Fatalf("killLine state: %q pos %d", b.string(), b.pos)
	}

	// killWord from different positions
	b.set("foo bar baz")
	b.home()
	b.right()
	b.killWord()
	if b.string() != "oo bar baz" {
		t.Fatalf("killWord at pos 1 got %q", b.string())
	}

	b.set("foo bar baz")
	b.home()
	for i := 0; i < 4; i++ {
		b.right()
	}
	b.killWord()
	if b.string() != "foo  baz" {
		t.Fatalf("killWord on space got %q", b.string())
	}
}

func TestInsertAndDeletion(t *testing.T) {
	var b buffer

	// Insert at beginning
	b.set("bc")
	b.home()
	b.insert('a')
	if b.string() != "abc" || b.pos != 1 {
		t.Fatalf("insert at beginning got %q pos %d", b.string(), b.pos)
	}

	// Insert at end
	b.set("abc")
	b.end()
	b.insert('d')
	if b.string() != "abcd" || b.pos != 4 {
		t.Fatalf("insert at end got %q pos %d", b.string(), b.pos)
	}

	// Insert at middle
	b.set("abde")
	b.left()
	b.insert('c')
	if b.string() != "abcde" || b.pos != 3 {
		t.Fatalf("insert in middle got %q pos %d", b.string(), b.pos)
	}

	// Backspace from middle
	b.set("abc")
	b.right()
	b.backspace()
	if b.string() != "ac" || b.pos != 0 {
		t.Fatalf("backspace from middle got %q pos %d", b.string(), b.pos)
	}

	// Delete forward from middle
	b.set("abc")
	b.backspace()
	b.deleteFwd()
	if b.string() != "a" || b.pos != 1 {
		t.Fatalf("deleteFwd from middle got %q pos %d", b.string(), b.pos)
	}
}

