func TestDecodeKeyEdgeCases(t *testing.T) {
	cases := map[string]keyKind{
		"\x02": keyLeft,  // Ctrl-B
		"\x06": keyRight, // Ctrl-F
		"\x10": keyUp,    // Ctrl-P
		"\x0e": keyDown,  // Ctrl-N
		"\x0b": keyKillToEnd,
		"\x15": keyKillLine,
		"\x17": keyKillWord,
		"\x08": keyBackspace, // another backspace code
		"\x00": keyNone,       // NUL
		"\x19": keyNone,       // control char, ignored
	}
	for input, want := range cases {
		got := decodeAll(t, input)
		if len(got) == 0 || got[0].kind != want {
			t.Fatalf("decode %q: got %+v, want kind %d", input, got, want)
		}
	}
}

func TestDecodeEscapeSequences(t *testing.T) {
	cases := map[string]keyKind{
		"\x1b[1~": keyHome,  // xterm home
		"\x1b[4~": keyEnd,   // xterm end
		"\x1b[5~": keyHome,  // xterm page up maps to home
		"\x1b[6~": keyEnd,   // xterm page down maps to end
		"\x1b[3~": keyDelete,
		"\x1bOH":  keyHome,  // rxvt
		"\x1bOF":  keyEnd,   // rxvt
	}
	for input, want := range cases {
		got := decodeAll(t, input)
		if len(got) == 0 || got[0].kind != want {
			t.Fatalf("decode %q: got %+v, want kind %d", input, got, want)
		}
	}
}

func TestDecodeUTF8Input(t *testing.T) {
	tests := []rune{'ä', 'ë', 'ï', 'ö', 'ü', 'ß', 'α', 'β', 'γ', 'δ'}
	for _, r := range tests {
		b := []byte(string(r))
		buf := bufio.NewReader(bytes.NewReader(b))
		got, err := decode(buf)
		if err != nil {
			t.Fatalf("decode UTF-8 %q: %v", r, err)
		}
		if got.kind != keyRune || got.r != r {
			t.Fatalf("decode UTF-8 %q: got %+v", r, got)
		}
	}
}

func TestHistoryEdgeCases(t *testing.T) {
	e := &Editor{hist: []string{}}

	// Empty history navigation
	var b buffer
	cursor := len(e.hist)
	stash := ""
	e.histPrev(&b, &cursor, &stash)
	if b.string() != "" || cursor != 0 {
		t.Fatalf("empty history prev: %q cursor %d", b.string(), cursor)
	}
	e.histNext(&b, &cursor, &stash)
	if b.string() != "" || cursor != 0 {
		t.Fatalf("empty history next: %q cursor %d", b.string(), cursor)
	}

	// Single item history
	e.hist = []string{"only"}
	cursor = len(e.hist)
	e.histPrev(&b, &cursor, &stash)
	if b.string() != "only" || cursor != 0 {
		t.Fatalf("single item prev: %q cursor %d", b.string(), cursor)
	}
	e.histPrev(&b, &cursor, &stash) // clamp
	if b.string() != "only" || cursor != 0 {
		t.Fatalf("clamp at first: %q cursor %d", b.string(), cursor)
	}
	e.histNext(&b, &cursor, &stash)
	e.histNext(&b, &cursor, &stash) // past end
	if b.string() != "only" || cursor != len(e.hist) {
		t.Fatalf("past end next: %q cursor %d", b.string(), cursor)
	}
}

