	if !strings.HasPrefix(top, "╭") || !strings.HasSuffix(top, "╮") {
		t.Fatalf("PromptTop missing rounded corners: %q", top)
	}
	if !strings.HasPrefix(bottom, "╰") || !strings.HasSuffix(bottom, "╯") {
		t.Fatalf("PromptBottom missing rounded corners: %q", bottom)
	}
	if visibleLen(top) != width || visibleLen(bottom) != width {
		t.Fatalf("Prompt borders width mismatch")
	}
}

func TestStylerColorDetection(t *testing.T) {
	// NO_COLOR disables
	t.Setenv("NO_COLOR", "1")
	t.Setenv("CLICOLOR_FORCE", "")
	s := Detect(nil)
	if s.Color {
		t.Fatal("NO_COLOR should disable styling")
	}

	// CLICOLOR_FORCE enables even for non-terminal
	t.Setenv("NO_COLOR", "")
	t.Setenv("CLICOLOR_FORCE", "1")
	s = Detect(nil)
	if !s.Color {
		t.Fatal("CLICOLOR_FORCE should enable styling")
	}

	// Default without env vars depends on file type
	t.Setenv("NO_COLOR", "")
	t.Setenv("CLICOLOR_FORCE", "")
	s = Detect(nil)
	// Detect(nil) should return disabled for non-TTY
	if s.Color {
		t.Log("Warning: Detect(nil) returned Color=true for nil file")
	}
}

