func TestRowPadding(t *testing.T) {
	s := Styler{Color: false}
	width := 30

	// Short text
	row := s.Row("", "", "short", width)
	plain := "short"
	pad := width - 2 - 1 - len(plain) // inner - lead - space
	expectedContent := " short" + strings.Repeat(" ", pad)
	if !strings.Contains(row, expectedContent) {
		t.Fatalf("Row padding wrong: %q", row)
	}

	// Empty text
	row = s.Row("", "", "", width)
	if !strings.Contains(row, "  ") {
		t.Fatalf("Row with empty text: %q", row)
	}
}

