func TestReportStatusConcurrent(t *testing.T) {
	f, sock := startFakeHerdr(t)
	c := New(Env{Active: true, SocketPath: sock, PaneID: "p"})

	// Concurrent status updates
	done := make(chan bool)
	for i := 0; i < 5; i++ {
		go func() {
			c.ReportStatus(agent.StatusWorking)
			done <- true
		}()
	}
	for i := 0; i < 5; i++ {
		<-done
	}

	// Should see at most one working report due to dedup
	waitFor(t, func() bool { return len(f.recorded()) >= 1 })
	reqs := f.recorded()
	workingCount := 0
	for _, req := range reqs {
		if req.Method == "pane.report_agent" && req.Params["state"] == "working" {
			workingCount++
		}
	}
	if workingCount > 1 {
		t.Fatalf("expected at most 1 working report, got %d", workingCount)
	}
}

