func TestMultipleClientsConcurrent(t *testing.T) {
	f, sock := startFakeHerdr(t)
	c1 := New(Env{Active: true, SocketPath: sock, PaneID: "p1"})
	c2 := New(Env{Active: true, SocketPath: sock, PaneID: "p2"})

	// Concurrent reports from different clients
	done := make(chan bool)
	for i := 0; i < 5; i++ {
		go func(id int) {
			c := c1
			if id%2 == 1 {
				c = c2
			}
			c.ReportStatus(agent.StatusIdle)
			done <- true
		}(i)
	}
	for i := 0; i < 5; i++ {
		<-done
	}

	waitFor(t, func() bool { return len(f.recorded()) >= 5 })
	reqs := f.recorded()

	panes := make(map[string]int)
	for _, req := range reqs {
		paneID, _ := req.Params["pane_id"].(string)
		panes[paneID]++
	}
	if len(panes) != 2 {
		t.Fatalf("expected reports from 2 panes, got %d: %+v", len(panes), panes)
	}
}

func TestStatusEnumValues(t *testing.T) {
	// Verify all status values map correctly
	cases := map[agent.AgentStatus]string{
		agent.StatusIdle:     "idle",
		agent.StatusWorking:  "working",
		agent.StatusBlocked:  "blocked",
		agent.StatusDone:     "done", // special handling
	}

	for status, expectedState := range cases {
		f, sock := startFakeHerdr(t)
		c := New(Env{Active: true, SocketPath: sock, PaneID: "p"})

		c.ReportStatus(status)

		if status == agent.StatusDone {
			// Done uses release_agent
			waitFor(t, func() bool { return len(f.recorded()) >= 1 })
			req := f.recorded()[0]
			if req.Method != "pane.release_agent" {
				t.Errorf("StatusDone method = %s, want pane.release_agent", req.Method)
			}
		} else {
			waitFor(t, func() bool { return len(f.recorded()) >= 1 })
			req := f.recorded()[0]
			state, _ := req.Params["state"].(string)
			if state != expectedState {
				t.Errorf("Status %s state = %s, want %s", status, state, expectedState)
			}
		}
	}
}

