func TestReportSurvivesSlowResponse(t *testing.T) {
	// Start a server that accepts connection but doesn't respond
	ln, err := net.Listen("unix", filepath.Join(t.TempDir(), "slow.sock"))
	if err != nil {
		t.Fatal(err)
	}
	defer ln.Close()

	c := New(Env{Active: true, SocketPath: ln.Addr().String(), PaneID: "p"})

	done := make(chan bool)
	go func() {
		c.ReportStatus(agent.StatusWorking)
		done <- true
	}()

	select {
	case <-done:
		// Success
	case <-time.After(3 * time.Second):
		t.Fatal("ReportStatus hung on slow response")
	}
}

